protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Preserve EF8 discriminator property name ("Discriminator" instead of EF9 default "$type")
    // so existing documents and raw SQL queries like
    // SELECT * FROM c WHERE c.Discriminator = 'Blog' continue to work.
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve EF8 compound id format ("Blog|1") so existing documents remain accessible.
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // REMOVED: HasIndex — Cosmos DB provider now throws at startup.
    // Manage indexing via Azure Portal, Bicep, or Terraform instead.
}

